INSERT INTO activity_artifacts VALUES('66e468e0-7699-447e-abeb-5511135663c9','c5e8ecf8-9e24-41c4-a256-3f78b9f1341c',NULL,'app_blueprint','2fdaca10-172a-4bde-b970-46ac8c73845a.app-blueprint.json',unistr('{\u000a  "id": "todo-list-blueprint",\u000a  "name": "Todo List Blueprint",\u000a  "version": 1,\u000a  "description": "作成・編集・完了切替に集中した、画面内一時データの Todo List 画面の設計。検索や複雑な整理は外し、新規入力と一覧操作が一直線につながる最小構成にする。",\u000a  "designPreset": {\u000a    "id": "nightworkers-default",\u000a    "name": "NightWorkers Default",\u000a    "mode": "hybrid",\u000a    "theme": "nightworkers-dark",\u000a    "density": "compact",\u000a    "radius": "default",\u000a    "shadow": "subtle",\u000a    "fontScale": "default",\u000a    "contrast": "standard",\u000a    "motion": "standard"\u000a  },\u000a  "screens": [\u000a    {\u000a      "id": "todo-list",\u000a      "name": "Todo List",\u000a      "path": "/todo-list",\u000a      "componentName": "ListPage",\u000a      "sections": [\u000a        {\u000a          "kind": "custom_section",\u000a          "id": "todo-entry",\u000a          "title": "新規 Todo 入力",\u000a          "name": "todo-entry-section",\u000a          "root": {\u000a            "kind": "layout",\u000a            "layout": "stack",\u000a            "props": {\u000a              "gap": "md",\u000a              "padding": "none"\u000a            },\u000a            "children": [\u000a              {\u000a                "kind": "component",\u000a                "id": "todo-entry-card",\u000a                "component": "Card",\u000a                "props": {\u000a                  "title": "Todo を追加する",\u000a                  "description": "タイトル、詳細、期限をその場で入力して、一覧にすぐ反映できる構成です。まずは追加操作が最短で届くようにします。",\u000a                  "tone": "neutral"\u000a                },\u000a                "layout": {\u000a                  "width": "full"\u000a                },\u000a                "children": [\u000a                  {\u000a                    "kind": "layout",\u000a                    "layout": "grid",\u000a                    "props": {\u000a                      "columns": 2,\u000a                      "gap": "md"\u000a                    },\u000a                    "children": [\u000a                      {\u000a                        "kind": "component",\u000a                        "id": "todo-title-field",\u000a                        "component": "InputGroup",\u000a                        "props": {\u000a                          "label": "タイトル",\u000a                          "placeholder": "例: 買い物メモを作る",\u000a                          "helpText": "一覧で最初に見える主要情報です。"\u000a                        },\u000a                        "layout": {\u000a                          "width": "full"\u000a                        },\u000a                        "children": []\u000a                      },\u000a                      {\u000a                        "kind": "component",\u000a                        "id": "todo-due-field",\u000a                        "component": "Input",\u000a                        "props": {\u000a                          "label": "期限",\u000a                          "placeholder": "例: 2026-06-15",\u000a                          "helpText": "期限やリマインドの前提として表示します。"\u000a                        },\u000a                        "layout": {\u000a                          "width": "full"\u000a                        },\u000a                        "children": []\u000a                      },\u000a                      {\u000a                        "kind": "component",\u000a                        "id": "todo-detail-field",\u000a                        "component": "InputGroup",\u000a                        "props": {\u000a                          "label": "詳細メモ",\u000a                          "placeholder": "例: 予算、持ち物、確認事項",\u000a                          "helpText": "タイトルだけでは足りない内容を補います。"\u000a                        },\u000a                        "layout": {\u000a                          "width": "full",\u000a                          "colSpan": 2\u000a                        },\u000a                        "children": []\u000a                      }\u000a                    ]\u000a                  },\u000a                  {\u000a                    "kind": "layout",\u000a                    "layout": "row",\u000a                    "props": {\u000a                      "gap": "sm",\u000a                      "align": "end"\u000a                    },\u000a                    "children": [\u000a                      {\u000a                        "kind": "component",\u000a                        "id": "todo-remind-switch",\u000a                        "component": "Switch",\u000a                        "props": {\u000a                          "label": "期限を有効にする",\u000a                          "checked": true\u000a                        },\u000a                        "layout": {\u000a                          "width": "auto"\u000a                        },\u000a                        "children": []\u000a                      },\u000a                      {\u000a                        "kind": "component",\u000a                        "id": "todo-add-button",\u000a                        "component": "Button",\u000a                        "props": {\u000a                          "label": "追加する",\u000a                          "variant": "primary"\u000a                        },\u000a                        "layout": {\u000a                          "width": "auto"\u000a                        },\u000a                        "children": []\u000a                      }\u000a                    ]\u000a                  }\u000a                ]\u000a              }\u000a            ]\u000a          },\u000a          "actions": [\u000a            {\u000a              "id": "add-todo",\u000a              "label": "追加する",\u000a              "type": "submit",\u000a              "target": "todo-create"\u000a            }\u000a          ]\u000a        },\u000a        {\u000a          "kind": "preset_section",\u000a          "id": "todo-workspace",\u000a          "name": "todo-workspace-section",\u000a          "preset": "table_workspace",\u000a          "props": {\u000a            "title": "Todo 一覧",\u000a            "description": "作成した Todo を、完了状態の切り替えと編集のしやすさを優先して一覧表示します。検索や複雑な絞り込みは置かず、見る場所を迷わせません。",\u000a            "toolbar": {\u000a              "text": "3件の Todo"\u000a            },\u000a            "filters": [],\u000a            "table": {\u000a              "columns": [\u000a                {\u000a                  "key": "done",\u000a                  "label": "完了",\u000a                  "type": "status"\u000a                },\u000a                {\u000a                  "key": "title",\u000a                  "label": "タイトル",\u000a                  "type": "text"\u000a                },\u000a                {\u000a                  "key": "detail",\u000a                  "label": "詳細",\u000a                  "type": "text"\u000a                },\u000a                {\u000a                  "key": "due-date",\u000a                  "label": "期限",\u000a                  "type": "date"\u000a                },\u000a                {\u000a                  "key": "actions",\u000a                  "label": "操作",\u000a                  "type": "actions"\u000a                }\u000a              ],\u000a              "rows": [\u000a                {\u000a                  "id": "todo-1",\u000a                  "done": "未完了",\u000a                  "title": "買い物メモを作る",\u000a                  "detail": "夕食の材料と日用品をまとめる",\u000a                  "due-date": "2026-06-13",\u000a                  "actions": [\u000a                    "編集",\u000a                    "完了にする"\u000a                  ]\u000a                },\u000a                {\u000a                  "id": "todo-2",\u000a                  "done": "完了",\u000a                  "title": "会議資料を確認する",\u000a                  "detail": "提出前に数字と表記を見直す",\u000a                  "due-date": "2026-