     \"title\": \"週末の予定を整理する\",\n                  \"detail\": \"やることを短く書き出す\",\n                  \"due-date\": \"2026-06-16\",\n                  \"actions\": [\"編集\", \"完了にする\"]\n                }\n              ],\n              \"emptyState\": {\n                \"title\": \"Todo はまだありません\",\n                \"description\": \"上の入力欄から1件追加すると、ここに一覧が表示されます。\",\n                \"actions\": [\n                  {\n                    \"label\": \"Todo を追加する\",\n                    \"type\": \"primary\"\n                  }\n                ]\n              }\n            }\n          },\n          \"overrides\": [],\n          \"actions\": [\n            {\n              \"id\": \"toggle-complete\",\n              \"label\": \"完了にする\",\n              \"type\": \"custom\",\n              \"target\": \"todo-toggle\"\n            },\n            {\n              \"id\": \"open-edit\",\n              \"label\": \"編集\",\n              \"type\": \"open\",\n              \"target\": \"todo-edit\"\n            }\n          ]\n        }\n      ],\n      \"actions\": [\n        {\n          \"id\": \"create-todo\",\n          \"label\": \"Todo を追加\",\n          \"type\": \"submit\",\n          \"target\": \"todo-create\"\n        }\n      ]\n    }\n  ],\n  \"databaseSchema\": {\n    \"tables\": [],\n    \"relations\": []\n  },\n  \"dataBindings\": [],\n  \"implementationTasks\": [\n    {\n      \"id\": \"todo-ui-layout\",\n      \"title\": \"Todo 入力と一覧のレイアウトを実装する\",\n      \"description\": \"新規 Todo 入力カードと一覧テーブルを上下に並べ、作成直後に一覧へ視線が流れる構成を実装する。入力項目はタイトル、詳細、期限、完了切替の最小構成にする。\",\n      \"affectedDomains\": [\n        \"blueprint-ui\",\n        \"blueprints\"\n      ]\n    },\n    {\n      \"id\": \"todo-inline-edit-flow\",\n      \"title\": \"編集と完了切替の操作導線を実装する\",\n      \"description\": \"一覧の各行に編集と完了切替を置き、編集時は画面内で内容を確認しやすい導線を用意する。完了状態は行の見た目でも判別できるようにする。\",\n      \"affectedDomains\": [\n        \"blueprint-ui\",\n        \"blueprint-task-planning\"\n      ]\n    },\n    {\n      \"id\": \"todo-storage-decision\",\n      \"title\": \"画面内一時データの保存方法を DB Design で検討する\",\n      \"description\": \"今回は永続化を前提にしないため、ローカル状態のみで完結するか、将来の保存先をどう拡張するかを DB Design で整理する。table/column/relation はこの Blueprint では定義しない。\",\n      \"affectedDomains\": [\n        \"blueprint-data\",\n        \"blueprint-binding\",\n        \"blueprint-task-planning\"\n      ]\n    }\n  ],\n  \"learningHooks\": [\n    {\n      \"id\": \"todo-add-flow-check\",\n      \"trigger\": \"Todo を追加した直後\",\n      \"note\": \"追加後に一覧の先頭へ反映され、入力を続けやすいかを確認する。\"\n    },\n    {\n      \"id\": \"todo-complete-toggle-check\",\n      \"trigger\": \"完了状態を切り替えた直後\",\n      \"note\": \"完了/未完了の差が視認できるか、行の情報密度が崩れないかを確認する。\"\n    }\n  ]\n}","jsonRepair":{"repaired":false,"repairKind":"none"},"referenceDocuments":[{"id":"root","kind":"root","source":"builtin","relativePath":"SKILL.md","digest":"sha256:2ff3bd38b65592c36bb1165a7725e5ea47413d8f5deba9581ca005935a40204c"},{"id":"router","kind":"router","source":"builtin","relativePath":"references/router.md","digest":"sha256:fdae67217ca454b917c2d2cf6cffedd4b3a786c68b7126540a3c0428a3f2d9a5"},{"id":"plan","kind":"phase","source":"builtin","relativePath":"references/phases/plan.md","digest":"sha256:05eb475bf24f72c4d25a593ef51ab7cd66244320e8a403e7cc13dccfe63f78de"},{"id":"planning","kind":"mode","source":"builtin","relativePath":"references/modes/planning.md","digest":"sha256:c973a103a50811e6f94c924abbe319c703a8cc84cf5eda69462523acdd2d7352"},{"id":"review","kind":"mode","source":"builtin","relativePath":"references/modes/review.md","digest":"sha256:88b49f5fb40c4f7bf3294d8dc32b604b5b2ef730f0aba7c9c405ab6fee0bd83c"},{"id":"blueprint","kind":"work_kind","source":"builtin","relativePath":"references/work_kinds/blueprint.md","digest":"sha256:77791dc9fdd07a5c5b07f607ec5d96bcf50963a54bbd183022bf5b7b54003fca"},{"id":"ui_ux","kind":"work_kind","source":"builtin","relativePath":"references/work_kinds/ui_ux.md","digest":"sha256:82fd62debbd08d209353b00944994d3e41ac0a349efbf317a26