INSERT INTO design_questionnaire_question_sets VALUES('a76e9cc2-aeb9-41ea-a791-aff81c10947f',1781271678,1781271678,'92998520-f6cd-4532-afc3-88e0879e243c',1,'{"version":1,"source":{"taskId":"c5e8ecf8-9e24-41c4-a256-3f78b9f1341c","repositoryId":"984c8844-643e-4596-93a5-703a8d14a1e0","sourceKind":"plan_mode_intake","blueprintMessageId":null},"title":"Todoリスト実装の確認フォーム","summary":"実装前に決めたい項目を選択式で確認します。","questionSets":[{"id":"choice-form","title":"Todoリスト実装の確認フォーム","category":"実装前確認","purpose":"実装に入る前に、未決定の仕様判断を選択式で確定します。","questions":[{"id":"q1","topic":"Question 1","question":"今回はどこまで作る方針ですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q1-o1","label":"最小構成の単体Todo一覧だけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o2","label":"作成・編集・完了切替まで含める","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o3","label":"タグや期限も含める","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o4","label":"共有や同期まで含める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-1"},{"id":"q2","topic":"Question 2","question":"Todo は何を前提に保存しますか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q2-o1","label":"画面内だけの一時データ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o2","label":"ローカル保存を使う","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o3","label":"サーバー保存を使う","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o4","label":"未定なので後で決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-2"},{"id":"q3","topic":"Question 3","question":"認証は必要ですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q3-o1","label":"不要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o2","label":"メールやパスワードで必要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o3","label":"既存アカウント連携が必要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o4","label":"今回は保留","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-3"},{"id":"q4","topic":"Question 4","question":"複数端末で同じデータを使う必要がありますか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q4-o1","label":"不要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o2","label":"同一端末内だけでよい","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o3","label":"複数端末同期が必要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o4","label":"今回は後続対応","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-4"},{"id":"q5","topic":"Question 5","question":"Todo に持たせたい情報はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"multi_choice","options":[{"id":"q5-o1","label":"タイトルだけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o2","label":"メモや詳細","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o3","label":"期限やリマインド","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o4","label":"優先度や並び順","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o5","label":"タグやカテゴリ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o6","label":"どれも不要","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-5"},{"id":"q6","topic":"Question 6","question":"完了した Todo の扱いはどうしますか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q6-o1","label":"削除だけできればよい","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o2","label":"完了状態を切り替えたい","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o3","label":"完了済みを非表示にしたい","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o4","label":"履歴として残したい","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-6"},{"id":"q7","topic":"Question 7","question":"通知やリマインドは必要ですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q7-o1","label":"不要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o2","label":"アプリ内の簡易通知だけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o3","label":"メール通知が必要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o4","label":"OS通知やプッシュ通知が必要","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-7"},{"id":"q8","topic":"Question 8","question":"検索や整理の機能はどの程度必要ですか？","why":"実装前に仕様判断が必要です。","answerType":"multi_choice","options":[{"id":"q8-o1","label":"不要","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o2","label":"検索だけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o3","label":"フィルタだけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o4","label":"ソートだけ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o5","label":"検索とフィルタの両方","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o6","label":"どれも不要","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-8"},{"id":"q9","topic":"Question 9","question":"見た目の方向性はどれが近いですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q9-o1","label":"最小で素朴な管理画面","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o2","label":"見やすさ重視の標準UI","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o3","label":"少しデザイン性のあるUI","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o4","label":"今回は既存デザインに合わせる","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-9"},{"id":"q10","topic":"Question 10","question":"今回は対象外にしたいものはありますか？","why":"実装前に仕様判断が必要です。","answerType":"multi_choice","options":[{"id":"q10-o1","label":"共有機能","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o2","label":"チーム管理","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o3","label":"外部連携","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o4","label":"通知機能","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o5","label":"同期機能","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o6","label":"今回は特にない","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-10"}]}],"openQuestions":[],"dbDesignHandoffNotes":[]}','{"title":"Todoリスト実装の確認フォーム","questions":[{"text":"今回はどこまで作る方針ですか？","type":"radio","options":["最小構成の単体Todo一覧だけ","作成・編集・完了切替まで含める","タグや期限も含める","共有や同期まで含める"]},{"text":"Todo は何を前提に保存しますか？","type":"radio","options":["画面内だけの一時データ","ローカル保存を使う","サーバー保存を使う","未定なので後で決める"]},{"text":"認証は必要ですか？","type":"radio","options":["不要","メールやパスワードで必要","既存アカウント連携が必要","今回は保留"]},{"text":"複数端末で同じデータを使う必要がありますか？","type":"radio","options":["不要","同一端末内だけでよい","複数端末同期が必要","今回は後続対応"]},{"text":"Todo に持たせたい情報はどれですか？","type":"checkbox","options":["タイトルだけ","メモや詳細","期限やリマインド","優先度や並び順","タグやカテゴリ","どれも不要"]},{"text":"完了した Todo の扱いはどうしますか？","type":"radio"